   404      if (sane)
   405      {
   406        hb_blob_make_immutable (blob);
   407        return blob;
   408      }
   409      else
   410      {
   411        hb_blob_destroy (blob);
   412        return hb_blob_get_empty ();
   413      }
   414    }
